import 'dart:convert';

import 'package:flutter/services.dart' show rootBundle;
import 'package:flutter_test/flutter_test.dart';

/// Integrity checks for assets/speed_tiers.json (the Champions speed tiers
/// generated by tool/build_champions_from_champout.js from the
/// projectpokemon/champout datamine; the tier columns are derived from base
/// Speed via the Level-50 formulas verified against all pokemon-zone.com rows).
void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  late Map<String, dynamic> tiersAsset;
  late Map<String, dynamic> championsAsset;
  late List<dynamic> tiers;
  late List<dynamic> pokedex;

  setUpAll(() async {
    tiersAsset =
        jsonDecode(await rootBundle.loadString('assets/speed_tiers.json'))
            as Map<String, dynamic>;
    championsAsset =
        jsonDecode(await rootBundle.loadString('assets/champions_seed.json'))
            as Map<String, dynamic>;
    tiers = tiersAsset['tiers'] as List<dynamic>;
    pokedex =
        jsonDecode(await rootBundle.loadString('assets/pokedex_seed.json'))
            as List<dynamic>;
  });

  group('speed_tiers.json integrity', () {
    test('has an updatedAt date, a source and a tiers list', () {
      expect(tiersAsset['updatedAt'], isA<String>());
      expect(tiersAsset['source'], contains('projectpokemon/champout'));
      expect(tiers, isA<List<dynamic>>());
    });

    test('covers the champions roster exactly (no gaps, no extras)', () {
      final rosterIds =
          (championsAsset['pokemon'] as List<dynamic>)
              .cast<Map<String, dynamic>>()
              .map((p) => p['id'] as int)
              .toSet();
      final tierIds =
          tiers.cast<Map<String, dynamic>>().map((t) => t['id'] as int).toSet();
      expect(tierIds, equals(rosterIds));
    });

    test('every tier id exists in pokedex_seed.json and matches its speed',
        () {
      final seedMap = {
        for (final p in pokedex.cast<Map<String, dynamic>>())
          p['id'] as int: p
      };
      for (final t in tiers.cast<Map<String, dynamic>>()) {
        final id = t['id'] as int;
        expect(seedMap.containsKey(id), isTrue, reason: 'tier id $id not in seed');
        expect(t['base'] as int, equals(seedMap[id]!['speed'] as int));
      }
    });

    test('no duplicate tier ids', () {
      final ids = tiers.cast<Map<String, dynamic>>().map((t) => t['id'] as int);
      expect(ids.toSet().length, equals(ids.length));
    });

    test('computed columns follow the Level-50 formulas', () {
      for (final t in tiers.cast<Map<String, dynamic>>()) {
        final base = t['base'] as int;
        expect(t['noInvest'] as int, equals(base + 20));
        expect(t['max'] as int, equals(base + 52));
        expect(t['maxPlus'] as int, equals(((base + 52) * 1.1).floor()));
        expect(t['min'] as int, equals(((base + 20) * 0.9).floor()));
        expect(t['scarf'] as int, equals((((base + 52) * 1.1).floor() * 1.5).floor()));
        expect(t['tailwind'] as int, equals(((base + 52) * 1.1).floor() * 2));
        expect(t['paralyzed'] as int, equals((((base + 52) * 1.1).floor() * 0.5).floor()));
      }
    });

    test('ranks are a valid competition ranking by base speed desc', () {
      int lastBase = 999;
      int lastRank = 0;
      int position = 0;
      for (final t in tiers.cast<Map<String, dynamic>>()) {
        position++;
        final base = t['base'] as int;
        if (base != lastBase) {
          lastBase = base;
          lastRank = position;
        }
        expect(t['rank'] as int, equals(lastRank));
      }
    });

    test('Floette speed data: seed #670 keeps the corrected 92, the roster carries Eternal Floette (#10061)',
        () {
      // Regression guard for the seed fix: base Floette's speed was once
      // baked as 52 (digit transposition of 92).
      final seedRow = pokedex
          .cast<Map<String, dynamic>>()
          .firstWhere((p) => p['id'] == 670);
      expect(seedRow['speed'] as int, 92);
      // The game data has no base Floette — the Champions roster carries the
      // Eternal Flower form instead, and its tier keeps the same base speed.
      final eternal = tiers
          .cast<Map<String, dynamic>>()
          .firstWhere((t) => t['id'] == 10061);
      expect(eternal['base'] as int, 92);
    });
  });
}
